//! Repository tasks.
//!
//! `cargo run -p xtask -- vectors --check` regenerates the shared test vectors in memory and fails if they differ from
//! `spec/vectors/`. `--update` writes them. Vectors are generated by Rust and checked by both the Rust and the JS tests.
//! Both modes first check that the label registry in `spec/SPEC.md` is exactly the set of labels generated here.
//!
//! `repo-check` checks what must hold on every commit: workflow dependencies pinned to commit SHAs and exact versions,
//! an npm package with an empty dependency tree, and the documents that name the current version. `release-check` runs
//! both and the release's own checks.
//!
//! `differential [--cases N] [--seed S]` runs the JS core against the Rust core on mutated vector inputs and requires
//! the same output or error code ([`differential`]).

mod differential;
mod generate;
mod ops;
mod resign;

use std::path::{Path, PathBuf};
use std::process::ExitCode;

/// One generated file: path relative to the repository root and its exact contents.
struct VectorFile {
    name: String,
    contents: String,
}

/// The purposes of every domain-separation label of format version 1, in the order of the registry in `spec/SPEC.md` §5.
const LABEL_PURPOSES: [&str; 19] = [
    "id",
    "event",
    "receipt",
    "locks",
    "vault",
    "contents",
    "wrap",
    "public",
    "login",
    "fetch",
    "change",
    "proof",
    "statement",
    "recovery/check",
    "recovery/sign",
    "recovery/box",
    "password/auth",
    "password/box",
    "peer",
];

/// Every vector file: `meta.json` and the generated files of [`generate::files`].
fn vector_files() -> Result<Vec<VectorFile>, String> {
    let label_list = LABEL_PURPOSES
        .iter()
        .map(|p| {
            format!(
                "    {{ \"purpose\": \"{p}\", \"label\": \"{}\" }}",
                rootcard::label(p, 1)
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    let meta = format!(
        "{{\n  \"format_version\": {},\n  \"api_version\": \"{}\",\n  \"label_prefix\": \"{}\",\n  \"labels\": [\n{}\n  ]\n}}\n",
        rootcard::FORMAT_VERSION,
        rootcard::API_VERSION,
        rootcard::LABEL_PREFIX,
        label_list
    );
    let mut files = vec![VectorFile {
        name: "spec/vectors/meta.json".into(),
        contents: meta,
    }];
    for (name, value) in generate::files()? {
        files.push(VectorFile {
            name: format!("spec/vectors/{name}"),
            contents: generate::pretty(&value),
        });
    }
    let registry = link_registry()?;
    files.push(VectorFile {
        name: "crates/rootcard/src/links_registry.rs".into(),
        contents: format!(
            "// Generated by `cargo run -p xtask -- vectors --update` from spec/links/*.json. Do not edit.\n\
             /// The descriptors of the service registry (SPEC [LNK-19]), as canonical JSON.\n\
             pub const REGISTRY: &str = r#\"{registry}\"#;\n"
        ),
    });
    files.push(VectorFile {
        name: "packages/rootcard/src/links-registry.js".into(),
        contents: format!(
            "// Generated by `cargo run -p xtask -- vectors --update` from spec/links/*.json. Do not edit.\n\n\
             /** The descriptors of the service registry (SPEC [LNK-19]), as canonical JSON. */\n\
             export const REGISTRY = {};\n",
            js_string(&registry)
        ),
    });
    Ok(files)
}

/// The service registry ([LNK-19]): every `spec/links/<service>.json`, checked by the core's descriptor parser, as one
/// canonical JSON array in file name order.
fn link_registry() -> Result<String, String> {
    let dir = repo_dir().join("spec/links");
    let mut names: Vec<String> = std::fs::read_dir(&dir)
        .map_err(|e| format!("{}: {e}", dir.display()))?
        .filter_map(|e| e.ok().map(|e| e.file_name().to_string_lossy().into_owned()))
        .filter(|n| n.ends_with(".json"))
        .collect();
    names.sort();
    let mut list = Vec::new();
    for name in names {
        let path = dir.join(&name);
        let bytes = std::fs::read(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        let v = rootcard::parse_json(&bytes).map_err(|e| format!("spec/links/{name}: {e}"))?;
        let d = rootcard::links::parse_descriptor(&v).map_err(|e| format!("spec/links/{name}: {e}"))?;
        if format!("{}.json", d.service) != name {
            return Err(format!(
                "spec/links/{name}: the file is named after its service ({})",
                d.service
            ));
        }
        list.push(v);
    }
    let text = String::from_utf8(rootcard::canonical(&rootcard::Value::Array(list))).map_err(|e| e.to_string())?;
    if text.contains("\"#") {
        return Err("spec/links: a descriptor contains \"#".into());
    }
    Ok(text)
}

/// A JavaScript string literal for `s`.
fn js_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\u{2028}' => out.push_str("\\u2028"),
            '\u{2029}' => out.push_str("\\u2029"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn repo_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// Every label-shaped string (`rootcard/<purpose>/v<n>`) in `text`, in order of appearance, without duplicates.
fn labels_in(text: &str) -> Vec<String> {
    let mut found: Vec<String> = Vec::new();
    for (start, _) in text.match_indices(rootcard::LABEL_PREFIX) {
        let rest = &text[start + rootcard::LABEL_PREFIX.len()..];
        let len = rest
            .find(|c: char| !(c.is_ascii_lowercase() || c.is_ascii_digit() || c == '/'))
            .unwrap_or(rest.len());
        let body = &rest[..len];
        let Some(slash) = body.rfind("/v") else { continue };
        let (purpose, version) = (&body[..slash], &body[slash + 2..]);
        if purpose.is_empty() || version.is_empty() || !version.bytes().all(|b| b.is_ascii_digit()) {
            continue;
        }
        let label = format!("{}{body}", rootcard::LABEL_PREFIX);
        if !found.contains(&label) {
            found.push(label);
        }
    }
    found
}

/// The label registry in `spec/SPEC.md` and the labels the code generates must be the same set (SPEC [DS-3]).
fn check_spec_labels() -> Result<(), String> {
    let path = repo_dir().join("spec/SPEC.md");
    let spec = std::fs::read_to_string(&path).map_err(|e| format!("reading {}: {e}", path.display()))?;
    let mut in_spec = labels_in(&spec);
    let mut generated: Vec<String> = LABEL_PURPOSES
        .iter()
        .map(|p| rootcard::label(p, rootcard::FORMAT_VERSION))
        .collect();
    in_spec.sort();
    generated.sort();
    if in_spec == generated {
        return Ok(());
    }
    let missing: Vec<&String> = generated.iter().filter(|l| !in_spec.contains(l)).collect();
    let extra: Vec<&String> = in_spec.iter().filter(|l| !generated.contains(l)).collect();
    Err(format!(
        "label registry mismatch: not in spec/SPEC.md: {missing:?}; in spec/SPEC.md but not generated: {extra:?}"
    ))
}

fn vectors(update: bool) -> Result<(), String> {
    check_spec_labels()?;
    let dir = repo_dir();
    let mut stale = Vec::new();
    for file in vector_files()? {
        let path = dir.join(&file.name);
        let current = std::fs::read_to_string(&path).unwrap_or_default();
        if current == file.contents {
            continue;
        }
        if update {
            std::fs::write(&path, &file.contents).map_err(|e| format!("writing {}: {e}", path.display()))?;
            println!("updated {}", file.name);
        } else {
            stale.push(file.name);
        }
    }
    if stale.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "stale vectors: {} (run `cargo run -p xtask -- vectors --update` only for an intended change)",
            stale.join(", ")
        ))
    }
}

/// The packages that are published together, each with its changelog (relative to the repository root).
const RELEASED: [(&str, &str); 4] = [
    ("rootcard (crate)", "crates/rootcard/CHANGELOG.md"),
    ("rootcard-host (crate)", "crates/rootcard-host/CHANGELOG.md"),
    ("rootcard-cli (crate)", "crates/rootcard-cli/CHANGELOG.md"),
    ("rootcard (npm)", "packages/rootcard/CHANGELOG.md"),
];

fn read(rel: &str) -> Result<String, String> {
    let path = repo_dir().join(rel);
    std::fs::read_to_string(&path).map_err(|e| format!("reading {}: {e}", path.display()))
}

/// The value of the first `key = "value"` line inside the TOML table `[table]` (enough for the workspace manifest).
fn toml_value(text: &str, table: &str, key: &str) -> Option<String> {
    let mut inside = false;
    for line in text.lines().map(str::trim) {
        if line.starts_with('[') {
            inside = line == format!("[{table}]");
            continue;
        }
        if !inside {
            continue;
        }
        if let Some(rest) = line.strip_prefix(key) {
            let rest = rest.trim_start().strip_prefix('=')?.trim();
            return quoted(rest);
        }
    }
    None
}

/// The first double-quoted string in `text`.
fn quoted(text: &str) -> Option<String> {
    let start = text.find('"')? + 1;
    let len = text[start..].find('"')?;
    Some(text[start..start + len].to_string())
}

/// The version of the workspace dependency on `rootcard` (`rootcard = { path = ..., version = "x" }`).
fn rootcard_dependency_version(manifest: &str) -> Option<String> {
    let mut inside = false;
    for line in manifest.lines().map(str::trim) {
        if line.starts_with('[') {
            inside = line == "[workspace.dependencies]";
            continue;
        }
        if inside && (line.starts_with("rootcard ") || line.starts_with("rootcard=")) {
            let at = line.find("version")?;
            return quoted(&line[at..]);
        }
    }
    None
}

/// `MAJOR.MINOR.PATCH` with an optional `-prerelease` of ASCII alphanumerics, `.` and `-`.
fn is_semver(version: &str) -> bool {
    let (core, pre) = match version.split_once('-') {
        Some((core, pre)) => (core, Some(pre)),
        None => (version, None),
    };
    let parts: Vec<&str> = core.split('.').collect();
    let numeric =
        |p: &&str| !p.is_empty() && p.bytes().all(|b| b.is_ascii_digit()) && (p.len() == 1 || !p.starts_with('0'));
    parts.len() == 3
        && parts.iter().all(numeric)
        && pre.is_none_or(|p| !p.is_empty() && p.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-'))
}

/// Whether `changelog` has a section heading for `version` (`## 1.2.3` or `## 1.2.3 - 2026-01-31`).
fn has_changelog_section(changelog: &str, version: &str) -> bool {
    changelog.lines().any(|line| {
        line.strip_prefix("## ")
            .and_then(|rest| rest.strip_prefix(version))
            .is_some_and(|rest| rest.is_empty() || rest.starts_with(' '))
    })
}

/// Problems with the third-party code that the workflows run ([`repo_check`]): every `uses:` is pinned to a full commit
/// SHA with the version in a comment, every tool installed with npm or `cargo install` has an exact version (and
/// `cargo install` uses `--locked`), and a nightly toolchain is dated.
fn workflow_problems(name: &str, text: &str) -> Vec<String> {
    let mut problems = Vec::new();
    for (n, line) in text.lines().enumerate() {
        let line = line.trim().trim_start_matches("- ");
        if let Some(rest) = line.strip_prefix("uses:") {
            let (target, comment) = rest
                .split_once(" #")
                .map_or((rest.trim(), ""), |(t, c)| (t.trim(), c.trim()));
            if target.starts_with("./") {
                continue;
            }
            let pinned = target.split_once('@').is_some_and(|(_, r)| {
                r.len() == 40 && r.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
            });
            if !pinned || comment.is_empty() {
                problems.push(format!(
                    "{name}:{}: `uses: {target}` must be pinned to a full commit SHA, with the tag in a comment",
                    n + 1
                ));
            }
        }
        if line.contains("cargo install") {
            let words: Vec<&str> = line.split_whitespace().collect();
            let exact = words.windows(2).any(|w| w[0] == "--version" && is_semver(w[1]))
                || words
                    .iter()
                    .any(|w| w.strip_prefix("--version=").is_some_and(is_semver))
                || words
                    .iter()
                    .any(|w| !w.starts_with('-') && w.rsplit_once('@').is_some_and(|(_, v)| is_semver(v)));
            if !exact || !words.contains(&"--locked") {
                problems.push(format!(
                    "{name}:{}: `cargo install` needs an exact `--version` and `--locked`",
                    n + 1
                ));
            }
        }
        if let Some(toolchain) = line.strip_prefix("toolchain:") {
            let toolchain = toolchain.split(" #").next().unwrap_or("").trim().trim_matches('"');
            if let Some(channel) = ["nightly", "beta"].iter().find(|c| toolchain.starts_with(**c)) {
                let date = toolchain[channel.len()..].strip_prefix('-').unwrap_or("");
                let dated = date.len() == 10
                    && date.bytes().enumerate().all(|(i, b)| {
                        if i == 4 || i == 7 {
                            b == b'-'
                        } else {
                            b.is_ascii_digit()
                        }
                    });
                if !dated {
                    problems.push(format!(
                        "{name}:{}: toolchain `{toolchain}` needs a date (`{channel}-YYYY-MM-DD`)",
                        n + 1
                    ));
                }
            }
        }
        if line.contains("npm install") || line.contains("npx ") {
            for word in line
                .split_whitespace()
                .filter(|w| w.contains('@') && !w.starts_with('@'))
            {
                let version = word.rsplit_once('@').map_or("", |(_, v)| v);
                if !is_semver(version) {
                    problems.push(format!("{name}:{}: `{word}` needs an exact version", n + 1));
                }
            }
        }
    }
    problems
}

/// The `package.json` keys that would give the npm package a dependency tree or run code when it is installed. The
/// package has zero runtime and zero dev dependencies (AGENTS.md rule 6), so `npm audit` has nothing to audit and none
/// of these may appear.
const NPM_FORBIDDEN_KEYS: [&str; 10] = [
    "dependencies",
    "devDependencies",
    "peerDependencies",
    "optionalDependencies",
    "bundleDependencies",
    "bundledDependencies",
    "overrides",
    "preinstall",
    "install",
    "postinstall",
];

/// Problems with the npm package's manifest ([`repo_check`]): a key of [`NPM_FORBIDDEN_KEYS`] anywhere in it. Keys are
/// matched as quoted JSON keys (`"name":`), so the check needs no JSON parser and also catches a nested key.
fn npm_manifest_problems(name: &str, text: &str) -> Vec<String> {
    let mut problems = Vec::new();
    for key in NPM_FORBIDDEN_KEYS {
        let quoted_key = format!("\"{key}\"");
        let found = text
            .match_indices(&quoted_key)
            .any(|(at, _)| text[at + quoted_key.len()..].trim_start().starts_with(':'));
        if found {
            problems.push(format!(
                "{name}: `{key}` is not allowed: the package has no dependencies and no install scripts"
            ));
        }
    }
    problems
}

/// Problems with the documents that name the released version ([`repo_check`]). These are the documents that release
/// 0.2.0 and 0.2.1 left saying 0.1.0 and "no version has been released".
fn version_doc_problems(version: &str, readme: &str, security: &str) -> Vec<String> {
    let mut problems = Vec::new();
    if !readme.contains(&format!("Status: **{version}")) {
        problems.push(format!(
            "README.md: the status line must start with `Status: **{version}`"
        ));
    }
    let line = match version.split('.').collect::<Vec<_>>().as_slice() {
        ["0", minor, ..] => format!("| 0.{minor}.x "),
        [major, ..] => format!("| {major}.x "),
        _ => String::new(),
    };
    if !security.lines().any(|l| l.starts_with(&line) && l.contains("Yes")) {
        problems.push(format!(
            "SECURITY.md: the supported versions table needs a row `{}| Yes |` for {version}",
            line.trim_end().to_owned() + " "
        ));
    }
    problems
}

/// Checks that hold on every commit, not only for a release: pinned workflow dependencies, an npm package without
/// dependencies or install scripts, and documents that name the current version. Run by CI and by [`release_check`].
fn repo_check() -> Result<(), String> {
    let mut problems = Vec::new();
    let dir = repo_dir().join(".github/workflows");
    let mut names: Vec<_> = std::fs::read_dir(&dir)
        .map_err(|e| format!("{}: {e}", dir.display()))?
        .filter_map(|e| e.ok().map(|e| e.file_name().to_string_lossy().into_owned()))
        .filter(|n| n.ends_with(".yml") || n.ends_with(".yaml"))
        .collect();
    names.sort();
    for name in names {
        let path = format!(".github/workflows/{name}");
        problems.extend(workflow_problems(&path, &read(&path)?));
    }
    for path in ["packages/rootcard/package.json", "tests/browser/package.json"] {
        if repo_dir().join(path).exists() {
            problems.extend(npm_manifest_problems(path, &read(path)?));
        }
    }
    if repo_dir().join("packages/rootcard/package-lock.json").exists() {
        problems.push("packages/rootcard/package-lock.json: the package has no dependencies to lock".to_string());
    }
    let manifest = read("Cargo.toml")?;
    let version =
        toml_value(&manifest, "workspace.package", "version").ok_or("Cargo.toml: no version in [workspace.package]")?;
    problems.extend(version_doc_problems(
        &version,
        &read("README.md")?,
        &read("SECURITY.md")?,
    ));
    if problems.is_empty() {
        Ok(())
    } else {
        Err(format!("repository check failed:\n  - {}", problems.join("\n  - ")))
    }
}

/// Every check a release must pass before anything is published (docs/RELEASING.md). Returns the version.
fn release_check(tag: Option<&str>) -> Result<String, String> {
    let mut problems = Vec::new();
    let manifest = read("Cargo.toml")?;
    let version =
        toml_value(&manifest, "workspace.package", "version").ok_or("Cargo.toml: no version in [workspace.package]")?;
    if !is_semver(&version) {
        problems.push(format!("workspace version {version:?} is not MAJOR.MINOR.PATCH[-pre]"));
    }
    if version == "0.0.0" {
        problems.push("version 0.0.0 is the name placeholder (PLAN D2); bump it first".to_string());
    }
    match rootcard_dependency_version(&manifest) {
        Some(v) if v == version => {}
        other => problems.push(format!(
            "[workspace.dependencies] rootcard version is {other:?}, expected {version:?}"
        )),
    }
    let package = read("packages/rootcard/package.json")?;
    let npm_version = package
        .find("\"version\"")
        .and_then(|at| quoted(package[at + 9..].trim_start_matches([' ', ':'])));
    if npm_version.as_deref() != Some(version.as_str()) {
        problems.push(format!(
            "packages/rootcard/package.json version is {npm_version:?}, expected {version:?}"
        ));
    }
    for (name, changelog) in RELEASED {
        if !has_changelog_section(&read(changelog)?, &version) {
            problems.push(format!("{changelog}: no `## {version}` section for {name}"));
        }
    }
    if let Some(tag) = tag
        && tag != format!("v{version}")
    {
        problems.push(format!(
            "tag {tag:?} does not match the version (expected \"v{version}\")"
        ));
    }
    if let Err(e) = vectors(false) {
        problems.push(e);
    }
    if let Err(e) = repo_check() {
        problems.push(e);
    }
    if problems.is_empty() {
        Ok(version)
    } else {
        Err(format!("release check failed:\n  - {}", problems.join("\n  - ")))
    }
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let result = match args.iter().map(String::as_str).collect::<Vec<_>>().as_slice() {
        ["vectors", "--check"] | ["vectors"] => vectors(false),
        ["vectors", "--update"] => vectors(true),
        ["repo-check"] => repo_check(),
        ["release-check"] => release_check(None).map(|v| println!("{v}")),
        ["release-check", "--tag", tag] => release_check(Some(tag)).map(|v| println!("{v}")),
        ["differential", options @ ..] => differential::differential(options),
        _ => Err("usage: cargo run -p xtask -- vectors [--check | --update]\n       \
                  cargo run -p xtask -- repo-check\n       \
                  cargo run -p xtask -- release-check [--tag vX.Y.Z]\n       \
                  cargo run -p xtask -- differential [--cases N] [--seed S]"
            .into()),
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("{e}");
            ExitCode::FAILURE
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_labels_and_ignores_lookalikes() {
        let text = "`rootcard/id/v1`, rootcard/recovery/sign/v1. rootcard/id/v1 again, rootcard/ and rootcard/x/vy";
        assert_eq!(labels_in(text), ["rootcard/id/v1", "rootcard/recovery/sign/v1"]);
    }

    #[test]
    fn label_purposes_are_unique() {
        for (i, p) in LABEL_PURPOSES.iter().enumerate() {
            assert!(!LABEL_PURPOSES[i + 1..].contains(p), "duplicate purpose {p}");
        }
    }

    #[test]
    fn spec_registry_matches() {
        assert_eq!(check_spec_labels(), Ok(()));
    }

    #[test]
    fn semver() {
        for ok in ["0.1.0", "1.2.3", "10.0.1", "0.1.0-rc.1", "1.0.0-alpha-2"] {
            assert!(is_semver(ok), "{ok}");
        }
        for bad in ["1.2", "1.2.3.4", "01.2.3", "1.2.x", "1.2.3-", "v1.2.3", "1.2.3+build"] {
            assert!(!is_semver(bad), "{bad}");
        }
    }

    #[test]
    fn changelog_sections() {
        let log = "# Changelog\n\n## Unreleased\n\n## 0.1.0 - 2026-11-20\n\n## 0.1.0-rc.1\n";
        assert!(has_changelog_section(log, "0.1.0"));
        assert!(has_changelog_section(log, "0.1.0-rc.1"));
        assert!(!has_changelog_section(log, "0.1"));
        assert!(!has_changelog_section(log, "0.2.0"));
    }

    #[test]
    fn reads_the_workspace_manifest() {
        let manifest = "[workspace]\n[workspace.package]\nversion = \"0.3.1\"\n\n[workspace.dependencies]\n\
                        rootcard = { path = \"crates/rootcard\", version = \"0.3.1\" }\n";
        assert_eq!(
            toml_value(manifest, "workspace.package", "version").as_deref(),
            Some("0.3.1")
        );
        assert_eq!(rootcard_dependency_version(manifest).as_deref(), Some("0.3.1"));
    }
    #[test]
    fn workflow_pins() {
        let sha = "11d5960a326750d5838078e36cf38b85af677262";
        let good = format!(
            "steps:\n      - uses: actions/checkout@{sha} # v4.4.0\n      - uses: ./local\n        run: npm install -g npm@11.21.2\n"
        );
        assert!(workflow_problems("w", &good).is_empty());
        for ok in [
            "        run: cargo install cargo-fuzz --version 0.13.2 --locked\n",
            "        run: cargo install --locked cargo-fuzz@0.13.2\n",
            "        run: cargo install --locked --version=0.13.2 cargo-fuzz\n",
            "          toolchain: nightly-2026-11-05\n",
            "          toolchain: \"1.95\"\n",
            "          toolchain: stable\n",
        ] {
            assert!(workflow_problems("w", ok).is_empty(), "{ok}");
        }
        for bad in [
            "      - uses: actions/checkout@v4\n".to_string(),
            format!("      - uses: actions/checkout@{sha}\n"),
            format!("      - uses: actions/checkout@{} # v4\n", sha.to_uppercase()),
            format!("      - uses: actions/checkout@{} # v4\n", &sha[..39]),
            "        run: npm install -g npm@^11.5.1\n".to_string(),
            "        run: npm install -g npm@latest\n".to_string(),
            "        run: cargo install cargo-fuzz --locked\n".to_string(),
            "        run: cargo install cargo-fuzz --version 0.13 --locked\n".to_string(),
            "        run: cargo install cargo-fuzz --version 0.13.2\n".to_string(),
            "          toolchain: nightly\n".to_string(),
            "          toolchain: \"nightly-2026-11\"\n".to_string(),
            "          toolchain: beta # latest\n".to_string(),
        ] {
            assert_eq!(workflow_problems("w", &bad).len(), 1, "{bad}");
        }
    }

    #[test]
    fn npm_manifest() {
        let good = r#"{ "name": "rootcard", "scripts": { "test": "node --test", "build": "node tools/x.mjs" },
                       "description": "no dependencies", "files": ["src/"] }"#;
        assert!(npm_manifest_problems("p", good).is_empty());
        for bad in [
            r#"{ "dependencies": {} }"#,
            r#"{ "devDependencies" : { "x": "1.0.0" } }"#,
            r#"{ "optionalDependencies":{} }"#,
            r#"{ "bundledDependencies": [] }"#,
            r#"{ "overrides": {} }"#,
            r#"{ "scripts": { "postinstall": "node x.js" } }"#,
            r#"{ "scripts": { "install": "node-gyp rebuild" } }"#,
        ] {
            assert_eq!(npm_manifest_problems("p", bad).len(), 1, "{bad}");
        }
    }

    #[test]
    fn version_docs() {
        let security = "| Version | Supported |\n|---|---|\n| 0.2.x | Yes |\n| 0.1.x | No |\n";
        assert!(version_doc_problems("0.2.1", "> Status: **0.2.1, pre-1.0.**", security).is_empty());
        assert_eq!(
            version_doc_problems("0.2.1", "> Status: **0.1.0, pre-1.0.**", security).len(),
            1
        );
        assert_eq!(
            version_doc_problems("0.3.0", "> Status: **0.3.0, pre-1.0.**", security).len(),
            1
        );
        assert_eq!(version_doc_problems("0.1.4", "> Status: **0.1.4**", security).len(), 1);
        assert!(version_doc_problems("1.2.0", "Status: **1.2.0**", "| 1.x | Yes |").is_empty());
    }

    #[test]
    fn this_repository_passes() {
        repo_check().unwrap();
    }
}
